package dev.mainul35.cms.sdk.runtime;

import java.util.Map;

/**
 * Event envelope sent by a client component. {@code eventId} is generated by the client and
 * makes retries idempotent: the runtime answers a repeated id with the original result.
 */
public record RuntimeEvent(
        String eventId,
        String type,
        String pluginId,
        String componentId,
        String instanceId,
        String page,
        Map<String, Object> payload) {

    public RuntimeEvent {
        payload = payload == null ? Map.of() : Map.copyOf(payload);
    }

    @SuppressWarnings("unchecked")
    public <T> T payload(String name, Class<T> type) {
        Object v = payload.get(name);
        return type.isInstance(v) ? (T) v : null;
    }
}
